// findingSelectedStyles colours the selected row by the severity under the
// cursor. It is what refreshSelectionStyle did, minus its own bounds check.
func findingSelectedStyles(f scan.Finding) table.Styles {
	return theme.TableStylesForSeverity(string(f.Severity))
}

// Tab constants for results view
const (
	TabCVE       = 0
	TabSecrets   = 1
	TabLicense   = 2
	TabMisconfig = 3
	TabCIScore   = 4
	tabCount     = 5
)

// updateFindingsTable populates the findings table based on active tab and filters.
//
// The tab is this view's own filter, not the component's: it selects which
// findings exist at all, where a FilterBar query narrows a list that is already
// settled. The severity went the other way — it is four cumulative tokens the
// table owns (Rule 136), which is what gave `.` back to the sort.
func (m *Model) updateFindingsTable() {
	if m.result == nil {
		return
	}

	m.findingsTable.SetItems(m.filterFindingsByTab())
	// A change of tab or severity is a change of scope, not a shorter list, so
	// the cursor goes back to the top and the columns are measured again.
	// SetItems deliberately does neither on its own.
	m.findingsTable.GotoTop()
	m.findingsTable.Remeasure()
}

// tabCategory maps a tab to the finding category it shows.
//
// The tabs and scan.Result's counters are now the same classification, applied
// once in scan.Categorize: they were two rules that disagreed on three inputs,
// each of which produced a finding counted in the header but present in no tab
// at all — visible nowhere, which is the worst way for a finding to be wrong.
var tabCategory = map[int]scan.Category{
	TabCVE:       scan.CategoryVulnerability,
	TabSecrets:   scan.CategorySecret,
	TabLicense:   scan.CategoryLicense,
	TabMisconfig: scan.CategoryMisconfiguration,
	TabCIScore:   scan.CategoryCIScore,
}

// filterFindingsByTab returns findings filtered by the active tab
func (m *Model) filterFindingsByTab() []scan.Finding {
	if m.result == nil {
		return nil
	}

	want, ok := tabCategory[m.activeTab]
	if !ok {
		return nil
	}
	var filtered []scan.Finding
	for _, f := range m.result.Findings {
		if scan.Categorize(f) == want {
			filtered = append(filtered, f)
		}
	}
	return filtered
}

// sourceDisplay returns a display string for the source column.
//
// Which tool found it, not which category it is — the tab already says the
// category, and telling gitleaks from trivy-secret in the Secrets tab is the
// point of showing both there.
func sourceDisplay(f scan.Finding) string {
	switch f.Source {
	case scan.SourceTrivyLicense:
		return "license"
	case scan.SourceTrivyMisconfig:
		return "misconfig"
	case scan.SourceGitleaks:
		return "gitleaks"
	case scan.SourceTrivySecret:
		return "trivy"
	case scan.SourceTrivy:
		return "vuln"
	default:
		return f.Source
	}
}

// countFindingsByTab returns the count of findings for each tab. These are the
// numbers on the tab labels, and scan.Result's counters are the same ones.
func (m *Model) countFindingsByTab() (cve, secrets, licenses, misconfigs, ci int) {
	if m.result == nil {
		return 0, 0, 0, 0, 0
	}

	for _, f := range m.result.Findings {
		switch scan.Categorize(f) {
		case scan.CategoryVulnerability:
			cve++
		case scan.CategorySecret:
			secrets++
		case scan.CategoryLicense:
			licenses++
		case scan.CategoryMisconfiguration:
			misconfigs++
		case scan.CategoryCIScore:
			ci++
		}
	}
	return cve, secrets, licenses, misconfigs, ci
}

// switchTab switches to the given tab index and refreshes the table
func (m *Model) switchTab(tab int) {
	m.activeTab = tab
	// The CI tab carries a score line above the table, so the height changes
	// with the tab and not only with the window.
	m.resizeFindings()
	m.footer.Clear()
	m.updateFindingsTable()
}

// handleIgnoreSecret prompts confirmation to ignore a secret finding.
//
// Gitleaks findings only. .gitleaksignore is matched on a Gitleaks fingerprint,
// which a Trivy secret does not have — AddToGitleaksIgnore would fabricate one
// from the file and rule, write it, and report success for a line Gitleaks will
// never match and Trivy never reads. Refusing says so instead.
func (m Model) handleIgnoreSecret() (tea.Model, tea.Cmd) {
	if exclude := m.canExclude(); !exclude.Enabled() {
		return m, m.footer.Warn(exclude.Reason)
	}
	finding, _ := m.findingsTable.Selected()
	m.findingToIgnore = &finding
	m.confirmModal = sharedcomponents.NewConfirmModal(
		"Ignore Secret",
		fmt.Sprintf("Add this secret to .gitleaksignore?\n\nFile: %s\nRule: %s", finding.File, finding.ID),
	)
	return m, nil
}

// The two findings actions, and why each does not apply (Rule 130).
const (
	reasonNoFinding    = "No finding selected"
	reasonNotASecret   = ".gitleaksignore only holds secrets — open the Secrets tab"
	reasonNotGitleaks  = "Only Gitleaks findings can be added to .gitleaksignore"
	reasonNotCITab     = "The resolved pipeline belongs to the CI tab"
	reasonNotARepo     = "An image has no pipeline"
	reasonNoResolution = "This forge does not resolve a pipeline server-side"
	reasonNothingToSee = "No finding to open"
)

// canOpenFinding reports whether enter has a row to detail.
func (m Model) canOpenFinding() shortcut.Availability {
	if _, ok := m.findingsTable.Selected(); !ok {
		return shortcut.Unavailable(reasonNothingToSee)
	}
	return shortcut.Availability{}
}

// canExclude reports whether X applies to the selected finding.
//
// .gitleaksignore is matched on a Gitleaks fingerprint, which a Trivy secret
// does not have — fabricating one would report success for a line nothing will
// ever match. The tab is checked first because it is the coarser answer: on
// the CVE tab the key means nothing at all, whatever the row.
// openPipelineKey opens the pipeline the forge resolves for this repository.
//
// It is a **declared exception** to the uppercase vocabulary
// (keymap.DeclaredExceptions), on the precedent of `c` in oci/network-inspect
// and for the reason written there: the action exists on one sub-screen, and
// burning one of the three remaining free capitals for it would cost more than
// it returns.
//
// `o` and not `p`: `o` already means "open what this screen points at" in this
// view's details state, where it opens a finding's reference. One verb, two
// screens, and the shortcut column is replaced by the mode either way.
const openPipelineKey = "o"

// canOpenPipeline decides whether the resolved pipeline can be fetched.
//
// The tab is checked first for canExclude's reason — it is the coarser answer,
// and off the CI tab the key means nothing whatever the row. The shape is
// checked before anything is read: a GitHub context cannot answer this at all,
// and finding that out after a keystroke and a git call would be worse than
// saying so in the column.
func (m Model) canOpenPipeline() shortcut.Availability {
	switch {
	case m.activeTab != TabCIScore:
		return shortcut.Unavailable(reasonNotCITab)
	case m.result == nil || m.result.TargetType != scan.TargetDirectory:
		return shortcut.Unavailable(reasonNotARepo)
	case !forge.ShapeFor(m.config.Forge.Type).MergedCIConfig:
		return shortcut.Unavailable(reasonNoResolution)
	}
	return shortcut.Availability{}
}

// openResolvedPipeline hands the document to the router, which opens the
// viewer on it. The fetch is the source's, so it runs on the viewer's own Cmd
// (Rule 110) and its failures are reported where the document would have been.
func (m Model) openResolvedPipeline() (tea.Model, tea.Cmd) {
	// The refusal is never silent (Rule 130), and it is a Warn rather than an
	// Error: nothing failed, the key does not apply as asked (Rule 128). The
	// reason is the one canOpenPipeline computed, so the footer and the greyed
	// entry cannot be about different things.
	if a := m.canOpenPipeline(); !a.Enabled() {
		return m, m.footer.Warn(a.Reason)
	}
	source := pipelineSource{
		RepoPath: m.result.Target,
		Label:    shortenHome(m.result.Target),
		Forge:    m.config.Forge,
		Secrets:  m.secrets,
		Findings: m.result.Findings,
	}
	return m, func() tea.Msg { return uiviewer.OpenRequestMsg{Source: source} }
}

func (m Model) canExclude() shortcut.Availability {
	if m.activeTab != TabSecrets {
		return shortcut.Unavailable(reasonNotASecret)
	}
	finding, ok := m.findingsTable.Selected()
	switch {
	case !ok:
		return shortcut.Unavailable(reasonNoFinding)
	case finding.Source != scan.SourceGitleaks:
		return shortcut.Unavailable(reasonNotGitleaks)
	}
	return shortcut.Availability{}
}

// handleResultsState processes input in results state.
//
// The search answers first, and every key below is unreachable while it has the
// keyboard: "c" is a character in a query, "esc" cancels the search rather than
// leaving the results, and "enter" confirms it rather than opening a finding.
// The inventory has had this guard since it gained a bar; this state gained one
// the day the severity floor became tokens, and never got the guard with it.
func (m Model) handleResultsState(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	if m.findingsTable.InEditMode() {
		return m, m.findingsTable.Update(msg)
	}
	switch msg.String() {
	case "esc":
		// No origin view means this view was opened directly, so esc stays
		// inside it and goes back to whichever landing state it opened on.
		if m.OriginView == "" {
			return m.goHome()
		}
		return m, func() tea.Msg { return BackToOriginMsg{Origin: m.OriginView} }
	case "enter":
		if finding, ok := m.findingsTable.Selected(); ok {
			// The details view is about a finding, not about a row index — an
			// index would name a different one the moment the list changed
			// under it, which is how workspaces got D24.
			m.selectedFinding = &finding
			m.state = StateDetails
			m.detailsViewport.Width = m.width
			m.detailsViewport.Height = m.height
			m.detailsViewport.SetContent(m.buildDetailsContent())
			m.detailsViewport.GotoTop()
		}
		return m, nil
	case "ctrl+r":
		m.activeTab = TabCVE
		return m.goHome()
	case "tab":
		m.switchTab((m.activeTab + 1) % tabCount)
		return m, nil
	case "shift+tab":
		m.switchTab((m.activeTab + tabCount - 1) % tabCount)
		return m, nil
	// 1-4 jumped straight to a tab. They were the application's only numeric
	// bindings, and an exception in a single view is precisely what §3.26
	// dismantles — tab reaches all four.
	case "c", "h", "m", "l":
		return m.toggleSeverity(msg.String())
	case keymap.Exclude:
		return m.handleIgnoreSecret()
	case openPipelineKey:
		return m.openResolvedPipeline()
	}
	// `.` is the sort again, and the search and the severity tokens are the
	// table's (Rule 136).
	return m, m.findingsTable.Update(msg)
}

// toggleSeverity flips one severity token. Cumulative: c and h together ask for
// "CRITICAL or HIGH", which is the question a threshold cycle could not put.
func (m Model) toggleSeverity(key string) (tea.Model, tea.Cmd) {
	label := map[string]string{"c": "critical", "h": "high", "m": "medium", "l": "low"}[key]
	m.findingsTable.SetTokenActive(label, !m.findingsTable.IsTokenActive(label))
	m.findingsTable.GotoTop()
	return m, nil
}

// resizeFindings lays the findings table out. Every tab gets the whole height:
// the CI tab used to give two rows to a score line above the table, and losing
// two findings on one tab out of five — for a letter the inventory already
// carries per target — was not worth the jump on every tab switch.
func (m *Model) resizeFindings() {
	m.findingsTable.Resize(m.width, max(m.height, 5))
}

package security

import (
	"github.com/charmbracelet/bubbles/spinner"
	"github.com/charmbracelet/bubbles/viewport"
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/credentials"
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/scan"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// ViewState represents the current state of the security view.
//
// There were five. StateInput was the form, and StateScanning the screen that
// ran one scan in place while the user watched it — both went with the form
// (phase 3). What replaced them is the inventory, which rescans in the
// background with a spinner on the row, so nothing waits on a whole screen.
type ViewState int

const (
	StateInventory ViewState = iota // What this context has scanned, read from the caches
	StateResults                    // Displaying results summary
	StateDetails                    // Showing detailed findings
)

// Model represents the security scanner view
type Model struct {
	config *config.Config
	// secrets is the context's store, used only to load the forge token for a
	// CI scan. Nothing else here reads a credential.
	secrets credentials.Storage
	width   int
	height  int

	state  ViewState
	result *scan.Result

	// Inventory state
	inventory datatable.Model[scanTarget]
	// spinner animates the rows being rescanned; it is stamped onto them by
	// setInventory, because a Cell function is built once and cannot reach here.
	//
	// It survives only to produce the tick Cmd. What lands in a cell is
	// spinnerFrameIdx, because spinner.View() renders through a style and a
	// table cell carries no escape sequence (Rule 122).
	spinner         spinner.Model
	spinnerFrameIdx int

	// jobs is the router snapshot of everything running anywhere, and jobFrame
	// the spinner frame that goes with it — bare, because it lands in a table
	// cell (Rule 122). See jobs.go: scanTarget.Scanning is derived from it, so
	// there is no in-flight state here to carry across a reload.
	jobs     []jobs.Run
	jobFrame string

	// inventoryLoading is true while loadInventoryCmd is in flight. It exists
	// because an empty table and a table that has not answered yet look the
	// same, and they mean opposite things: "Nothing scanned yet" asserted
	// before the caches were read is a claim the view cannot make, and the one
	// the user saw flash by before the list appeared.
	//
	// It also keeps the spinner chain alive, which is why it is read by
	// spinnerAlive rather than only by the renderer.
	inventoryLoading bool

	// targetPath is what the result on screen is about — an image reference or a
	// repository path. It is the directory .gitleaksignore is written into, so
	// it is the key and never a display form.
	targetPath string
	// targetLabel is the same target folded for the title: the registry prefix
	// replaced by its alias, or the home directory by "~". It is a second field
	// rather than a folding applied to targetPath because the two are read for
	// opposite purposes — one is shown, the other is written to disk, and an
	// aliased path names a directory that does not exist.
	targetLabel string

	// Results state
	findingsTable datatable.Model[scan.Finding]
	// selectedFinding is what the details view is showing. It holds the finding
	// rather than its row index, so a list that changes underneath cannot make
	// the details describe a different one.
	selectedFinding *scan.Finding
	activeTab       int // 0=CVE, 1=Secrets, 2=Licenses, 3=Misconfig

	// OriginView is the view to return to when Esc is pressed in StateResults.
	// Set by the app router when opening this view from workspaces or
	// oci_resources. Empty when the results were opened from the inventory,
	// which is inside this view and needs no round trip.
	OriginView command.ViewType

	// footer is the one line of transient state below the viewport (Rule 128).
	footer sharedcomponents.FooterMessage

	// Details view scrollable viewport
	detailsViewport viewport.Model

	// Ignore secret confirmation
	confirmModal    *sharedcomponents.ConfirmModal
	findingToIgnore *scan.Finding

	// scanAllModal carries the purge checkbox for A. It is separate from
	// confirmModal because the two answer different messages, and one field
	// holding either would make the handler guess which question was asked.
	scanAllModal *sharedcomponents.OptionConfirmModal
}

// New creates a new security scanner view, on the inventory.
// New builds the view. The secret store comes in at construction, like
// workspaces': the CI stage needs the context's forge token, and a rescan
// started here must produce the same grade as the same rescan started from ws —
// two screens grading one repository differently is the shape §3.11 and §3.12
// each had to undo.
func New(cfg *config.Config, secrets credentials.Storage) Model {
	s := spinner.New()
	s.Spinner = spinner.Dot
	s.Style = theme.SpinnerStyle()

	t := datatable.New(datatable.Config[scan.Finding]{
		Columns:        findingColumns(),
		SortColumn:     -1, // the order the scanner reported
		SelectedStyles: findingSelectedStyles,
		Tokens:         severityTokens(),
		TokenMatch:     matchesSeverity,
	})

	return Model{
		config:    cfg,
		secrets:   secrets,
		state:     StateInventory,
		inventory: newInventoryTable(cfg.Scan.EnableCIScore),
		// True from construction, because Init loads unconditionally: a view
		// that starts saying "not loading" would render the empty message for
		// the frame before the first Cmd runs.
		inventoryLoading: true,
		spinner:          s,
		findingsTable:    t,
	}
}

// ciForgeURL is the forge a repository must belong to for the CI column to be
// able to grade it — and the empty string when the column is off, which is what
// spares the loader a git call per row.
func ciForgeURL(cfg *config.Config) string {
	if cfg == nil || !cfg.Scan.EnableCIScore {
		return ""
	}
	return cfg.Forge.URL
}

func (m Model) ciForgeURL() string { return ciForgeURL(m.config) }

// severityTokens are the four cumulative severity filters (Rule 136).
//
// They replaced a cycle on `.` — which also cost the table its sort key. A
// cycle can only ask "at least this severe", and the question actually asked is
// "CRITICAL and HIGH", which is not a threshold: it excludes MEDIUM while
// including CRITICAL. Four toggles can say it and a cycle never could.
func severityTokens() []sharedcomponents.FilterToken {
	return []sharedcomponents.FilterToken{
		{Label: "critical"}, {Label: "high"}, {Label: "medium"}, {Label: "low"},
	}
}

// severityToken maps a finding's severity onto its token label. UNKNOWN has no
// token, so it is only ever hidden by an explicit choice of others.
var severityToken = map[scan.SeverityLevel]string{
	scan.SeverityCritical: "critical",
	scan.SeverityHigh:     "high",
	scan.SeverityMedium:   "medium",
	scan.SeverityLow:      "low",
}

// matchesSeverity keeps everything while no token is active: an empty filter
// means "no opinion", not "nothing".
func matchesSeverity(f scan.Finding, active map[string]bool) bool {
	if len(active) == 0 {
		return true
	}
	return active[severityToken[f.Severity]]
}

// NewWithPreloadedResult creates a security view showing a stored scan result.
// Used to display cached results without re-scanning (Rule 126).
func NewWithPreloadedResult(cfg *config.Config, secrets credentials.Storage, result *scan.Result) Model {
	m := New(cfg, secrets)
	m.state = StateResults
	m.result = result
	m.targetPath = result.Target
	m.targetLabel = labelForResult(cfg, result)
	m.activeTab = TabCVE
	// Filled here rather than waiting for the first WindowSizeMsg: the rows do
	// not depend on the width any more, so nothing was gained by deferring and
	// the table was empty until the terminal happened to report its size.
	m.updateFindingsTable()
	return m
}

// Init initializes the model
func (m Model) Init() tea.Cmd {
	return tea.Batch(
		m.spinner.Tick,
		// Loaded whatever the opening state: a view opened on a result returns
		// to the inventory on ctrl+r, and reading two small files is cheaper
		// than the branch that would decide not to.
		loadInventoryCmd(m.ciForgeURL()),
	)
}

// InEditMode reports whether a field or a modal has the keyboard, which is what
// stops the router claiming ":", "q" and "?" for itself.
//
// The results and details states used to be listed here too, for one reason: it
// was the only way to be handed esc. The router forwards esc unconditionally now
// (§1.3 D15), so those states are ordinary again — and get the command line, the
// help overlay and quit back with them.
func (m Model) InEditMode() bool {
	switch {
	case m.confirmModal != nil, m.scanAllModal != nil:
		return true
	case m.state == StateInventory:
		return m.inventory.InEditMode()
	case m.state == StateResults:
		// The findings table gained a filter bar with the severity tokens, so
		// this state has a focused field to declare like any other.
		return m.findingsTable.InEditMode()
	}
	return false
}

