// View renders the UI
func (m Model) View() string {
	// Show whichever modal is active (Rule 112: modals confirm, forms fill the
	// viewport).
	if modal := m.modalView(); modal != "" {
		return lipgloss.Place(
			m.width, m.height,
			lipgloss.Center, lipgloss.Center,
			modal,
			lipgloss.WithWhitespaceBackground(theme.ColorBackground),
		)
	}

	switch m.state {
	case StateInventory:
		return m.renderInventoryView()
	case StateResults:
		return m.renderResultsView()
	case StateDetails:
		return m.renderDetailsView()
	}
	return ""
}

// renderResultsView renders the results summary
func (m Model) renderResultsView() string {
	if m.result == nil {
		return "No results"
	}

	// A stage that failed is **not** rendered here. It goes to the log, and the
	// footer says to look there (Rule 128).
	//
	// It used to be a panel that replaced the whole table whenever
	// Result.Errors was non-empty, on the stated grounds that a failed scan has
	// no partial results to browse. That held while an error meant nothing had
	// run; it stopped holding the day a stage could fail beside three that
	// succeeded, and a plumber failure then took every CVE and every secret
	// down with it. Folding it to a banner above the table only moved the
	// problem — five tabs, permanently, for a message read once — and a tool's
	// stderr reformatted for a viewport is what a log is for.
	//
	// Nothing is lost by it: internal/scan logs every stage failure at the
	// point it records one, which it did not do before. The only copy of the
	// reason used to be on screen.
	//
	// The grade had a line of its own above the table on the CI tab, and it is
	// gone: it cost that tab two of its rows — the line and its blank — on
	// every open, to state a letter the inventory's own CI column carries per
	// target. A tab that shows fewer findings than its four neighbours, for a
	// value already on the previous screen, is not a trade worth making.
	return m.findingsTable.View()
}

// GetFooterHeight returns the footer height for this view (Rule 124).
func (m Model) GetFooterHeight() int {
	height := 2 // empty line + info line
	if m.showsResultTabs() {
		height = 3 // tab bar + empty line + info line
	}
	if bar := m.activeFilterBar(); bar != nil {
		height += bar.ExtraHeight() // Rule 136
	}
	return height
}

// RenderFooter returns the footer content rendered below the viewport (Rule 124).
//
// The bar comes first whatever the state, because its top edge *is* the
// viewport's bottom border (Rule 136) — the same order oci_resources uses for
// the one bar it draws above a tab bar.
//
// It is resolved through activeFilterBar, like the height. The results branch
// drew no bar at all while GetFooterHeight counted one, so the router took two
// lines off the viewport and nothing filled them: the table's bottom border
// climbed the moment a severity token went on, and the tokens the user had just
// switched on were nowhere on screen.
func (m Model) RenderFooter(width int) string {
	var parts []string
	if bar := m.activeFilterBar(); bar != nil {
		parts = append(parts, bar.View())
	}
	if m.showsResultTabs() {
		parts = append(parts, theme.PadWithBg(theme.Bg(" ")+m.renderTabs(), width))
	}
	parts = append(parts, theme.EmptyLineBg(width), m.renderInfoLine(width))
	return strings.Join(parts, "\n")
}

// modalView renders whichever modal is open, or "" when none is.
func (m Model) modalView() string {
	switch {
	case m.confirmModal != nil:
		return m.confirmModal.View()
	case m.scanAllModal != nil:
		return m.scanAllModal.View()
	}
	return ""
}

// FilterBarVisible reports whether the filter bar is on screen, which is what
// closes the viewport's bottom border around it (implements app.FilterBarView,
// Rule 136). Both tables have one now: the findings table gained the four
// severity tokens that used to be a cycle on `.`.
func (m Model) FilterBarVisible() bool {
	return m.activeFilterBar() != nil
}

// activeFilterBar is the bar of whichever table is on screen, or nil when the
// state has no table. One resolution rather than three, so GetFooterHeight and
// RenderFooter cannot disagree about whether the bar is there — which is the
// one way to make Rule 124's arithmetic wrong by a line.
func (m Model) activeFilterBar() *sharedcomponents.FilterBar {
	var bar *sharedcomponents.FilterBar
	switch {
	case m.state == StateInventory:
		bar = m.inventory.FilterBar()
	case m.showsResultTabs():
		bar = m.findingsTable.FilterBar()
	}
	if bar == nil || !bar.IsVisible() {
		return nil
	}
	return bar
}

// showsResultTabs reports whether the findings tab bar is on screen.
//
// A failed stage no longer takes it away, because nothing replaces the table
// any more: the tabs are what the results state is browsed with, and an empty
// one is an honest answer — the footer says which stage failed and where to
// read why.
func (m Model) showsResultTabs() bool {
	return m.state == StateResults && m.result != nil
}

// renderInfoLine is the footer's message line, always rendered even when empty
// (Rule 124). The message expires on its own after three seconds (Rule 128).
func (m Model) renderInfoLine(width int) string {
	return m.footer.View(width, m.status())
}

// status is what the footer says when no message is in flight.
//
// A stage that failed is a **state** of the result rather than an event: it is
// true for as long as the result is on screen, and a message would expire after
// three seconds — the distinction Rule 128 draws between the two. It carries
// the error level, because that is what happened, and it names the stages so
// the log can be searched for them.
func (m Model) status() sharedcomponents.Status {
	// A load in flight is a state too, and the only one the inventory has: the
	// table is on screen and empty, so without this line nothing distinguishes
	// "still reading the caches" from "nothing has ever been scanned".
	if m.state == StateInventory && m.inventoryLoading {
		return sharedcomponents.Status{Text: "Loading scan inventory...", Spinner: true}
	}
	if m.state != StateResults || m.result == nil || len(m.result.Errors) == 0 {
		return sharedcomponents.Status{}
	}
	return sharedcomponents.Status{
		Text:  failedStages(m.result.Errors) + " — check logs",
		Level: sharedcomponents.LevelError,
	}
}

// failedStages names what failed, reading the "<stage>: <reason>" that
// scan.recordStageError writes. The reason stays in the log: a footer is one
// line, and a tool's stderr is not.
func failedStages(errs []string) string {
	stages := make([]string, 0, len(errs))
	for _, e := range errs {
		stage := e
		if idx := strings.Index(e, ": "); idx != -1 {
			stage = e[:idx]
		}
		stages = append(stages, stage)
	}
	return strings.Join(stages, ", ") + " failed"
}

// renderTabs renders the tab bar
func (m Model) renderTabs() string {
	cve, secrets, licenses, misconfigs, ci := m.countFindingsByTab()

	return theme.RenderTabs([]theme.TabItem{
		{Label: fmt.Sprintf("CVE (%d)", cve)},
		{Label: fmt.Sprintf("Secrets (%d)", secrets)},
		{Label: fmt.Sprintf("Licenses (%d)", licenses)},
		{Label: fmt.Sprintf("Misconfig (%d)", misconfigs)},
		// The count, like its four neighbours — not the letter. A letter in a
		// column of counts would break the only thing the tab bar keeps
		// aligned, and the grade already has a line of its own below.
		{Label: fmt.Sprintf("CI (%d)", ci)},
	}, m.activeTab)
}
type Sizing int

const (
	// SizingUnset is the zero value, and means nothing. See the test above.
	SizingUnset Sizing = iota
	// SizingFixed takes exactly the width declared. For a count, a state, an
	// icon — anything whose size was known when the code was written.
	SizingFixed
	// SizingContent takes the width of its widest visible value, never below
	// MinWidth and never above MaxWidth. For paths, URLs, addresses, image
	// references: values whose length is a property of the data.
	SizingContent
)

// Column describes one column and how to get its value out of an item.
type Column[T any] struct {
	Title string
	// Sizing is the column's nature (see above). It has no default.
	Sizing Sizing
	// MinWidth is the width a SizingFixed column takes, and the floor a
	// SizingContent column is never squeezed under.
	//
	// It is a floor now, not the request it used to be: the shortfall comes out
	// of the content columns down to their MinWidth, and after that whole
	// columns are removed rather than emptied one cell at a time (widths.go).
	// The name stays MinWidth on a fixed column, where it *is* the width, for
	// the reason §3.45 gives: Width would be false on a content column that
	// grows past it, where MinWidth is merely redundant on a fixed one — a
	// redundant name is bearable, a false one is not.
	MinWidth int
	// MaxWidth caps a SizingContent column. 0 means no ceiling, and there is no
	// global default: a ceiling chosen once would apply to columns nobody has
	// looked at, and a full IPv6 address is 45 cells — so the first "reasonable"
	// default re-truncates exactly what the measurement was for. Meaningless on
	// SizingFixed, where MinWidth already is the width.
	MaxWidth int
	// Optional marks a column that may be dropped whole when the table does not
	// fit, before any column that is not. Orthogonal to Sizing because all four
	// combinations exist: the interface error counters have an exact width and
	// are also the first thing worth losing.
	Optional bool
	// DropFirst moves an Optional column to the head of the queue: it goes
	// before every other Optional one, wherever it sits on screen. Meaningless
	// without Optional, which is the flag that decides whether a column may go
	// at all.
	//
	// It exists because drop() reads the column order as an order of
	// importance, and that is true of every column whose place is chosen by
	// what it *is*. A gauge's place is chosen by what it *illustrates* — it has
	// to sit beside the number it draws, in the middle of the table, or it
	// stops being read as that number's picture (§3.71). Left to position
	// alone, the containers table would shed its I/O counters to keep two bars
	// that are the most expendable thing on the row.
	//
	// A bool rather than a rank: two tiers is what the case needs, and an int
	// would invite every table to number its columns against each other.
	DropFirst bool
	// TruncateHead cuts the start of an over-long value rather than its end.
	//
	// A flag per column rather than a rule derived from Sizing, because the
	// answer depends on the column and not on its nature: a URL, an image
	// reference and a path share their prefix and are told apart by their end,
	// while an address is identified by the network it starts with. It cannot
	// be left to Cell either — Cell does not know the width it will be rendered
	// at, and that is deliberate: it is what makes the value measurable.
	TruncateHead bool
	// Flex is the column's share of the space left over once every column has
	// what it wants. 0 takes no part; the leftover is split between the
	// flexible ones by weight.
	//
	// Flex says who receives the surplus, never who needs it — which is why it
	// cannot decide widths on its own: the ports table gave Process 110 cells
	// for "svchost.exe" at 200 columns while Peer Address stayed frozen at 26,
	// cutting an IPv6 endpoint in half. That is what Sizing answers.
	Flex int
	// Cell returns the text for this column. Plain text only: it is measured
	// and truncated before anything is applied to it, and runewidth counts an
	// escape sequence's bytes as width — a styled string is cut mid-escape and
	// bleeds over every row below it (Rule 122). Taking a string rather than a
	// styled value is what makes that unexpressible here.
	//
	// It must be pure and cheap. The rendering calls it once per visible cell;
	// the measurement calls it once per cell of every visible row, off screen
	// included. Nothing can check that — it is an arbitrary closure — so it is
	// stated here rather than tested.
	Cell func(T) string
	// Style colours the cell after it has been measured and truncated, which is
	// the only order in which colour is safe (see render.go). Nil leaves the
	// cell in the table's own colours.
	//
	// On a row a view has coloured whole via SelectedStyles (error, busy, a CVE
	// severity), it is not consulted: that row is handed to styles.Selected
	// whole, and a colour inside it would end the highlight mid-row. On the
	// plain "normal" selection it *is* consulted — see render.go's cellStyle,
	// which repaints the shared background on every cell instead of once on an
	// outer wrap, so per-cell colour and the highlight no longer fight.
	Style func(T) lipgloss.Style
	// Cut and TailStyle split a cell into two coloured runs instead of Style's
	// one: Style colours the first Cut(item) cells of the *finished* text —
	// already measured, truncated and padded to the column's width — and
	// TailStyle colours the rest. Both nil (the ordinary case, every column but
	// the containers load gauges) leaves Style covering the whole cell as
	// before.
	//
	// This is not the gradient Rule 122 forbids: nothing styled is ever
	// measured. Cut reads a plain, already-final string — the split happens
	// after truncation, at the same point Style already does its colouring —
	// so it is the same "measure first, colour after" order applied twice
	// instead of once, not an exception to it. It stays two runs rather than an
	// arbitrary list: one caller has needed it since it was added, and Cut, a
	// bare integer, is cheaper to reason about than a slice of spans that only
	// ever holds two elements.
	//
	// Dropped only for a row a view has coloured whole — error, busy, a CVE
	// severity — for the same reason Style is: a two-run cell still needs its
	// own reset between the runs, which that solid background cannot afford.
	// The plain "normal" selection consults both: each run repaints
	// ColorTableLineSelected and bold itself, the same per-cell repaint that makes a
	// single-run selected cell safe, so a load gauge keeps its fill/track
	// split under the cursor instead of collapsing to Style's colour alone.
	Cut       func(T) int
	TailStyle func(T) lipgloss.Style
	// Less sorts by this column. Nil means the column cannot be sorted by, and
	// `.` skips it.
	Less func(a, b T) bool
	// Search is what the text filter matches against. Nil means the column does
	// not participate.
	Search func(T) string
}

// Config is everything a view has to say about its table.
type Config[T any] struct {
	Columns []Column[T]
	// Tokens are the toggle filters shown in the bar (Rule 136).
	Tokens []components.FilterToken
	// TokenMatch decides whether an item passes the active toggles. Nil means
	// the toggles are ignored, which is only sensible with no Tokens.
	TokenMatch func(item T, active map[string]bool) bool
	// SortColumn is the column sorted by on open; -1 for no initial sort.
	SortColumn int
	// SortDesc opens the table on the descending order of SortColumn. It exists
	// for the count columns, where ascending is the useless end: an inventory
	// sorted by CRITICAL wants the worst target first, and cycling `.` past
	// ascending to reach it on every open is not a default.
	SortDesc bool
	// Key identifies an item across rebuilds, and is what the busy set is held
	// on. Nil switches the busy facility off entirely, which is the default:
	// most tables have no action to run on a row.
	//
	// It cannot be a `Busy func(T) bool` on this struct instead. Columns are
	// built once, in New, and close over nothing — imageRow exists because of
	// that — so a predicate here would have to close over the view's map of
	// in-flight actions, which is the same trap. Separating the identity from
	// the state is what avoids it, and it is also what lets IsBusy answer for an
	// object whose row does not exist yet: the guard on a confirm path runs
	// before anything is rebuilt.
	//
	// Keying on identity rather than a flag on the row is also what survives the
	// periodic refresh, which replaces the items while an action is running.
	Key func(T) string
	// StatusColumn is the column whose cell the spinner replaces while a row is
	// busy — the one that answers "what about this row". Ignored when Key is
	// nil.
	//
	// That column must not be sortable: askFor reserves width(Title)+2 for a
	// column carrying a Less, which is expensive for a glyph.
	StatusColumn int
	// SelectedStyles returns the table styles to use while the given item is
	// under the cursor — that is the only thing bubbles/table can vary per
	// selection, and it is what containers and security each re-derived by
	// hand. Returning a style rather than a state keyword is what keeps this
	// package from having to know what a severity is. Nil means the default.
	SelectedStyles func(T) table.Styles
}

)

func (m Model) GetShortcuts() shortcut.Shortcuts {
	switch m.state {
	case StateInventory:
		return m.inventoryShortcuts()
	case StateResults:
		return m.resultsShortcuts()
	case StateDetails:
		// A finding with no published reference is the same screen as one with
		// three, so `o` is greyed rather than dropped (Rule 130).
		f := m.selectedFinding
		return []shortcut.Shortcut{
			{Key: "esc", Description: "Back"},
			// keymap.Web, which is what handleDetailsState binds. It read
			// "o" and nothing answered it: the key advertised did nothing and
			// the key that worked was never shown — Rule 130's hazard seen
			// from the other side.
			{Key: keymap.Web, Description: "Open ref", Disabled: f == nil || len(f.References) == 0},
			{Key: "ctrl+p", Description: "Command"},
		}
	}
	return nil
}

// resultsShortcuts advertises the findings table's own keys.
//
// The four severity toggles were bound and unadvertised — a user had to open
// the help to learn the view filtered at all — and `.` was offered on three
// tabs out of four, from back when it cycled the severity floor. It is the sort
// now (Rule 111), so it applies wherever there is a table.
//
// While the search has the keyboard, everything else is a character: listing
// keys that no longer do what they say is worse than listing nothing, so only
// the two that end the search are shown. Same shape as the ports view.
func (m Model) resultsShortcuts() shortcut.Shortcuts {
	if m.findingsTable.InEditMode() {
		return shortcut.Shortcuts{{Key: "enter/esc", Description: "Confirm / Cancel search"}}
	}
	// X is greyed rather than dropped (Rule 130): a tab is not a different
	// screen, and the entry used to appear and disappear as the cursor crossed
	// a Trivy secret in a list holding both tools' findings.
	return []shortcut.Shortcut{
		{Key: "tab", Description: "Switch tab"},
		{Key: "enter", Description: "Details", Disabled: !m.canOpenFinding().Enabled()},
		{Key: "c", Description: "Toggle CRITICAL"},
		{Key: "h", Description: "Toggle HIGH"},
		{Key: "m", Description: "Toggle MEDIUM"},
		{Key: "l", Description: "Toggle LOW"},
		{Key: "/", Description: "Search"},
		{Key: ".", Description: "Sort"},
		{Key: keymap.Exclude, Description: "Exclude", Disabled: !m.canExclude().Enabled()},
		{Key: openPipelineKey, Description: "Open resolved pipeline", Disabled: !m.canOpenPipeline().Enabled()},
		{Key: "ctrl+r", Description: "New scan"},
		{Key: "ctrl+p", Description: "Command"},
		{Key: "?", Description: "Help"},
	}
}

// inventoryShortcuts advertises only what the selected row can actually do
// (Rule 130). An empty inventory offers none of the per-row actions, and a row
// with no stored counts cannot be opened.
// inventoryShortcuts is the landing state's column.
//
// An empty inventory is the same screen as a full one — the table is there,
// with no rows — so the row actions are greyed rather than dropped (Rule 130).
// The first scan of a context used to make four entries appear at once.
func (m Model) inventoryShortcuts() shortcut.Shortcuts {
	_, hasRow := m.inventory.Selected()
	return []shortcut.Shortcut{
		{Key: "enter", Description: "Open findings", Disabled: !m.canOpenTarget().Enabled()},
		{Key: keymap.Scan, Description: "Rescan", Disabled: !m.canRescanSelected().Enabled()},
		{Key: keymap.ScanAll, Description: "Rescan all", Disabled: !m.canRescanAll().Enabled()},
		{Key: "/", Description: "Filter", Disabled: !hasRow},
		{Key: "ctrl+r", Description: "Refresh"},
		{Key: "ctrl+p", Description: "Command"},
		{Key: "?", Description: "Help"},
	}
}

func (m Model) GetTitle() string {
	base := theme.IconSecurity + " Security Scanner"
	if m.state == StateInventory {
		return base + " " + theme.IconChevronRight + " Inventory"
	}
	// The label, not the key: the title is the one place the target is read
	// rather than used, and a registry prefix is what pushes the image's own
	// name off the line.
	if m.targetLabel != "" {
		annotation := lipgloss.NewStyle().
			Foreground(theme.ColorSecondary).
			Background(theme.ColorBackground).
			Render("(" + m.targetLabel + ")")
		return base + " " + annotation
	}
	return base
}

