func TestARegistryFailureIsThatEntrysReasonAlone(t *testing.T) {
	root := repoWith(t, map[string]string{"Dockerfile": "FROM alpine:3.18\n"})
	reg := newRegistry(nil)
	reg.err = errors.New("connection refused")

